const M=FinanceModel, $=s=>document.querySelector(s);
const euro=n=>n===null?'—':new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
const percent=n=>n===null?'Non calculable':new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1,signDisplay:'always'}).format(n)+' %';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#month').innerHTML=M.months.map((m,i)=>`<option value="${i+1}">${m}</option>`).join('');$('#month').value='9';M.divisions.forEach(d=>$('#division').add(new Option('Division '+d,d)));
let imported=null,readVersion=0;
const pages={dashboard:['Tableau de bord','Une vue claire de votre performance opérationnelle.'],income:['Compte de résultat','Une lecture commune des montants mensuels et cumulés.'],import:['Import des données','Un aperçu local, sans transmission ni enregistrement.'],controls:['Contrôles','Vérifications automatiques sur les données fictives.']};
const convention=`<div class="notice"><strong>Convention pédagogique :</strong> produits positifs, charges négatives. EBITDA = produits + achats et prestations + personnel + autres charges d’exploitation. Amortissements, résultat financier et impôts sur les bénéfices exclus. Variation = M − M-1 ; pourcentage = variation / |M-1| × 100. Janvier : M-1 indisponible (décembre 2025 absent). Pour une charge, une variation positive représente une diminution de charge.</div>`;
const bridge=`<div class="notice"><strong>Deux indicateurs, un même périmètre.</strong> EBITDA hors produits immobilisés = EBITDA − production immobilisée ACE − production immobilisée liée à la masse salariale. Les deux composantes sont déjà incluses dans les produits fictifs : elles ne s’ajoutent pas à l’EBITDA. Correspondance structurelle validée pour le prototype ; aucune règle comptable professionnelle certifiée. Les montants mensuels sont fictifs, exprimés en euros, et les cumuls sont calculés depuis janvier.</div>`;
let graphMetric='ebitda';
function table(head,rows){return `<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function render(){const page=pages[location.hash.slice(1)]?location.hash.slice(1):'dashboard';$('#page-title').textContent=pages[page][0];$('#subtitle').textContent=pages[page][1];document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.hash==='#'+page);if(a.hash==='#'+page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 const m=+$('#month').value,d=$('#division').value,c=M.total(m,d,false,+$('#year').value),p=M.total(m-1,d,false,+$('#year').value),y=M.total(m,d,true,+$('#year').value),v=M.variation(c.ebitda,p.ebitda),context=M.months[m-1]+' 2026 · '+(d==='all'?'Toutes les divisions':'Division '+d);
 if(page==='dashboard'){
 const bars=M.divisions.filter(x=>d==='all'||d===x).map(x=>[x,M.total(m,x)[graphMetric]]),max=Math.max(...bars.map(r=>r[1]));
 const trend=Array.from({length:m},(_,i)=>M.total(i+1,d)[graphMetric]),lo=Math.min(...trend)*.9,hi=Math.max(...trend)*1.05;
 const points=trend.map((value,i)=>`${20+i*460/Math.max(1,m-1)},${145-(value-lo)/(hi-lo)*125}`).join(' ');
 $('#screen').innerHTML=`<div class="cards"><article class="card primary"><div class="card-label">EBITDA du mois</div><div class="value">${euro(c.ebitda)}</div><div class="positive">${m>1?percent(v.percent)+' par rapport à M-1':'M-1 indisponible'}</div><small>${context}</small></article><article class="card"><div class="card-label">EBITDA cumulé</div><div class="value">${euro(y.ebitda)}</div><small>Janvier à ${M.months[m-1].toLowerCase()} 2026</small></article><article class="card"><div class="card-label">Variation mensuelle · M / M-1</div><div class="value">${m>1?(v.amount>0?'+':'')+euro(v.amount):'—'}</div><small>${m>1?percent(v.percent):'Décembre 2025 absent'}</small></article></div><section class="panel" style="margin-bottom:22px"><h2>EBITDA hors produits immobilisés</h2><p>Indicateur complémentaire · ${context}</p>${table(['Mois','Cumul depuis janvier','Variation M / M-1','Variation %'],[[euro(c.ebitdaExCapitalized),euro(y.ebitdaExCapitalized),m>1?euro(M.variation(c.ebitdaExCapitalized,p.ebitdaExCapitalized).amount):'—',m>1?percent(M.variation(c.ebitdaExCapitalized,p.ebitdaExCapitalized).percent):'—']])}<label style="margin-top:18px">Indicateur des graphiques<select id="graph-metric">${Object.entries(M.indicators).filter(([k])=>['ebitda','ebitdaExCapitalized'].includes(k)).map(([k,v])=>`<option value="${k}" ${k===graphMetric?'selected':''}>${v.label}</option>`).join('')}</select></label></section><div class="two-columns"><section class="panel"><div class="panel-head"><div><h2>${M.indicators[graphMetric].label} par division</h2><p>${context}</p></div><span class="badge">EUR</span></div>${bars.map(([division,value])=>`<div class="chart-row"><span>${division}</span><div class="track"><div class="bar" style="width:${value/max*100}%"></div></div><span class="chart-value">${euro(value)}</span></div>`).join('')}<div class="legend">● ${M.indicators[graphMetric].label} mensuel · montants fictifs</div></section><section class="panel"><h2>Évolution · ${M.indicators[graphMetric].label}</h2><p>Janvier au mois sélectionné · données fictives</p><svg class="sparkline" viewBox="0 0 500 175" role="img" aria-label="Évolution mensuelle, valeurs disponibles ci-dessous"><path d="M20 150H480" stroke="#e6edf2"/><polyline points="${points}" fill="none" stroke="#1da58b" stroke-width="3"/>${points.split(' ').map((pt,i)=>{const [x,y]=pt.split(',');return `<circle cx="${x}" cy="${y}" r="4" fill="#1da58b"><title>${M.months[i]} : ${euro(trend[i])}</title></circle>`;}).join('')}</svg><div class="month-labels">${M.months.slice(0,m).map(x=>`<span>${x.slice(0,3)}.</span>`).join('')}</div><details><summary>Consulter les valeurs</summary>${table(['Mois',M.indicators[graphMetric].label],trend.map((x,i)=>[M.months[i],euro(x)]))}</details></section></div>${convention}${bridge}`;
 $('#graph-metric').onchange=e=>{graphMetric=e.target.value;render();};
 }else if(page==='income'){
 const labels={revenue:'Produits d’exploitation',purchases:'Achats et prestations',payroll:'Charges de personnel',other:'Autres charges d’exploitation',ebitda:'<strong>EBITDA pédagogique</strong>',capitalizedACE:'À déduire : production immobilisée ACE',capitalizedPayroll:'À déduire : production immobilisée liée à la masse salariale',ebitdaExCapitalized:'<strong>EBITDA hors produits immobilisés</strong>'};
 $('#screen').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Compte de résultat simplifié</h2><p>${context} · montants en euros</p></div><span class="badge">FICTIF</span></div>${table(['Rubrique','Mois M','Mois M-1','Variation €','Variation %','Cumul janvier → M'],Object.entries(labels).map(([k,label])=>{const delta=M.variation(c[k],p[k]);return [label,euro(c[k]),m>1?euro(p[k]):'—',m>1?euro(delta.amount):'—',m>1?percent(delta.percent):'—',euro(y[k])];}))}</section>${convention}${bridge}<div class="notice">Le cumul est la somme des mois de janvier au mois sélectionné. Ce compte de résultat est limité aux rubriques nécessaires à l’EBITDA pédagogique ; il ne constitue pas un compte de résultat statutaire complet.</div>`;
 }else if(page==='controls'){
 const report=M.controls(m,d,+$('#year').value);
 $('#screen').innerHTML=`<div class="notice"><strong>Contrôles techniques sur données fictives — aucune validation comptable réelle.</strong> Statuts calculés, écart = calculé − attendu. Les consolidations portent toujours sur les cinq divisions fictives, sans liasse technique professionnelle. Les fichiers importés ne sont pas contrôlés.</div><section class="panel" style="margin-top:22px"><h2>Contrôles automatiques</h2><p>${context} · ${report.checks.filter(r=>r.status==='Conforme').length}/${report.checks.length} contrôles conformes</p>${report.issues.length?`<p class="error">${report.issues.map(esc).join(' · ')}</p>`:''}${table(['Contrôle','Attendu','Calculé','Écart','Statut'],report.checks.map(r=>[esc(r.label),euro(r.expected),euro(r.actual),euro(r.gap),`<span class="status ${r.status==='Conforme'?'ok':'bad'}">${r.status}</span>`]))}</section><details class="notice"><summary>Scénarios illustratifs distincts</summary><p>Conforme : écart nul ; Alerte : écart fictif injecté de 1 250 € ; Bloquant : écart fictif injecté de 15 000 €. Ces trois exemples ne sont pas les résultats des contrôles automatiques.</p></details>`;
 }else{
 $('#screen').innerHTML=`<section class="panel"><h2>Aperçu d’un fichier local</h2><p>Le fichier reste dans la mémoire de cet onglet et ne remplace pas la démonstration.</p><div class="dropzone" id="dropzone"><div class="upload-icon">↥</div><h3>Déposez votre fichier ici</h3><p>CSV UTF-8 · virgule ou point-virgule · 2 Mo maximum</p><label for="file">Ou choisissez un fichier CSV ou Excel<input id="file" type="file" accept=".csv,.xlsx,.xls"></label><small>Excel (.xlsx, .xls) : non pris en charge dans cette V2.</small></div><div style="margin-top:18px"><button id="sample">Télécharger un CSV fictif</button><button id="clear" class="secondary">Effacer l’aperçu</button></div><div id="import-result" class="import-result" aria-live="polite"></div></section><div class="notice">Aperçu structurel uniquement : aucune validation comptable ni intégration au tableau de bord. Les filtres du haut concernent les données de démonstration des autres écrans. Utilisez uniquement des fichiers fictifs. Recharger la page efface les données importées.</div>`;
 $('#file').onchange=e=>loadFile(e.target.files[0]);const zone=$('#dropzone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag');};zone.ondragleave=()=>zone.classList.remove('drag');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag');if(e.dataTransfer.files.length===1)loadFile(e.dataTransfer.files[0]);else showError('Déposez un seul fichier à la fois.');};
 $('#clear').onclick=()=>{readVersion++;imported=null;$('#file').value='';showPreview();};
 $('#sample').onclick=()=>{const csv='division;exercice;mois;produits;achats;personnel;autres_charges;production_immo_ace;production_immo_personnel\r\n'+M.data.map(r=>[r.division,r.year,r.month,r.revenue,r.purchases,r.payroll,r.other,r.capitalizedACE,r.capitalizedPayroll].join(';')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='financepilot-donnees-fictives.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};showPreview();
 }
}
function showError(msg){readVersion++;imported=null;const target=$('#import-result');if(target)target.innerHTML=`<p role="alert" class="error">${esc(msg)}</p>`;}
async function loadFile(file){if(!file)return;const version=++readVersion;imported=null;if(!/\.csv$/i.test(file.name)){showError('Format non pris en charge : Excel (.xlsx, .xls) indisponible. Choisissez un CSV UTF-8.');return;}if(file.size>2097152){showError('Limite dépassée : 2 Mo maximum.');return;}try{const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());if(version!==readVersion)return;imported={name:file.name,rows:M.parseCSV(text)};showPreview();}catch(e){if(version===readVersion)showError('Lecture impossible : '+e.message);}}
function showPreview(){const target=$('#import-result');if(!target)return;if(!imported){target.textContent='Aucun aperçu en mémoire.';return;}const {name,rows}=imported;target.innerHTML=`<h3>${esc(name)}</h3><p>${rows.length-1} lignes · ${rows[0].length} colonnes · 20 premières lignes affichées au maximum.</p>${table(rows[0].map(esc),rows.slice(1,21).map(r=>r.map(esc)))}`;}
$('#month').onchange=render;$('#division').onchange=render;$('#year').onchange=render;window.addEventListener('hashchange',render);render();
